    static getRowCount() {
        return parseInt(localStorage.getItem(this.table) || '0');
    }
}

class BigQuerySim {
  private static logs: AnalysisResult[] = [];
  static async insertRow(row: AnalysisResult) {
    this.logs.unshift(row);
